<style>
  @keyframes thinking {
    0% {
      /* clip-path: circle(50% at 50% 50%) */
      clip-path: inset(0% 0% 0% 0%);
    }
    44% {
      /* clip-path: circle(0% at 50% 50%) */
      clip-path: inset(0% 0% 0% 100%);
    }
    56% {
      /* clip-path: circle(0% at 50% 50%) */
      clip-path: inset(0% 100% 0% 0%);
    }
    100% {
      /* clip-path: circle(50% at 50% 50%) */
      clip-path: inset(0% 0% 0% 0%);
    }
  }

  .animate-thinking {
    animation: thinking 2s;
    animation-iteration-count: infinite;
  }
</style>
